package br.com.weg.workshop.post.controller; import br.com.weg.workshop.post.dto.*; import br.com.weg.workshop.post.service.PostService; import io.swagger.v3.oas.annotations.Operation; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/posts") public class PostController {private final PostService s;public PostController(PostService s){this.s=s;}@PostMapping @PreAuthorize("hasAnyRole('ARWEG','ADMIN')") public ResponseEntity<PostResponse> create(@Valid @RequestBody PostRequest r,Authentication a){return ResponseEntity.status(HttpStatus.CREATED).body(s.create(id(a),r));}@PutMapping("/{id}") @PreAuthorize("hasAnyRole('ARWEG','ADMIN')") public PostResponse update(@PathVariable UUID id,@Valid @RequestBody PostRequest r,Authentication a){return s.update(id(a),admin(a),id,r);}@PatchMapping("/{id}/schedule") @PreAuthorize("hasAnyRole('ARWEG','ADMIN')") public PostResponse schedule(@PathVariable UUID id,@Valid @RequestBody SchedulePostRequest r,Authentication a){return s.schedule(id(a),admin(a),id,r);}@PatchMapping("/{id}/publish") @PreAuthorize("hasAnyRole('ARWEG','ADMIN')") public PostResponse publish(@PathVariable UUID id,Authentication a){return s.publish(id(a),admin(a),id);}@PatchMapping("/{id}/archive") @PreAuthorize("hasAnyRole('ARWEG','ADMIN')") public PostResponse archive(@PathVariable UUID id,Authentication a){return s.archive(id(a),admin(a),id);}@GetMapping("/feed") @Operation(summary="List visible personalized feed posts") public Page<PostResponse> feed(@RequestParam(required=false) java.time.Instant updatedAfter,@PageableDefault(size=20,sort="publishedAt",direction=Sort.Direction.DESC) Pageable p,Authentication a){return s.feed(id(a),updatedAfter,p);}@PutMapping("/{id}/like") public ResponseEntity<Void> like(@PathVariable UUID id,Authentication a){s.like(id(a),id);return ResponseEntity.noContent().build();}@DeleteMapping("/{id}/like") public ResponseEntity<Void> unlike(@PathVariable UUID id,Authentication a){s.unlike(id(a),id);return ResponseEntity.noContent().build();}@PostMapping("/{id}/comments") public ResponseEntity<PostCommentResponse> comment(@PathVariable UUID id,@Valid @RequestBody CreateCommentRequest r,Authentication a){return ResponseEntity.status(HttpStatus.CREATED).body(s.comment(id(a),id,r));}@GetMapping("/{id}/comments") public Page<PostCommentResponse> comments(@PathVariable UUID id,@PageableDefault(size=20,sort="createdAt",direction=Sort.Direction.DESC) Pageable p,Authentication a){return s.comments(id(a),id,p);}private UUID id(Authentication a){return UUID.fromString(a.getName());}private boolean admin(Authentication a){return a.getAuthorities().stream().map(GrantedAuthority::getAuthority).anyMatch("ROLE_ADMIN"::equals);}}
